select 'msg_by_model', model, count(*), count(distinct scan_id), round(sum(tokens_in)), round(sum(tokens_out)) from tenant_xbow.agent_messages group by 2 order by 3 desc;
select 'turns_by_scan_bucket', b, count(*) scans, round(avg(finds),1) avg_finds from (with t as (select scan_id, max(turn_index)+1 turns from tenant_xbow.agent_messages where role='assistant' group by 1), f as (select scan_id, count(*) n from tenant_xbow.findings group by 1) select case when t.turns<=2 then '1-2' when t.turns<=5 then '3-5' else '6-8' end b, coalesce(f.n,0) finds from t left join f using (scan_id)) x group by 1 order by 1;
select 'findings_zero_turn_scans', count(*) from tenant_xbow.scans s where not exists (select 1 from tenant_xbow.agent_messages m where m.scan_id=s.scan_id) and exists (select 1 from tenant_xbow.findings f where f.scan_id=s.scan_id);